# --- [CELL 2]: ---

class SelectColumnsTransformer():

    def __init__(self, columns=None):
        self.columns = columns


    def transform(self, X, **transform_params):
        cpy_df = X[self.columns].copy()
        return cpy_df

    def fit(self, X, y=None, **fit_params):
        return self

